def _sort(values, axis=-1, direction='ASCENDING', stable=False, name=None):
    if direction == 'DESCENDING':
        values = np.negative(values)
    elif direction != 'ASCENDING':
        raise ValueError('Unrecognized direction: {}.'.format(direction))

