async def send_pending_messages(self):
    if not self.running:
        await self.open()
    try:
        pending = self._handler._pending_messages[:]  # Access pending messages
        await self._handler.wait_async()  # Wait for async operation
        results = []
        for m in pending:
            if m.state == constants.MessageState.SendFailed:
                results.append((False, MessageSendFailed(m._response)))  # Handle failed messages
            else:
                results.append((True, None))  # Handle successful messages
        return results
    except Exception as e:
        raise MessageSendFailed(e)  # Raise exception if any error occurs
```

