async def read(self, keys: List[str]) -> dict:
    try:
        # Check if the database and container exist, create if not
        if not self.__container_exists:
            self.__create_db_and_container()

        if len(keys) > 0:
            # Create parameters object
            parameters = [{'name': f'@id{i}', 'value': f'{self.__sanitize_key(key)}'} for i, key in enumerate(keys)]
            parameter_sequence = ','.join(param.get('name') for param in parameters)

            # Create the query
            query = {
                "query": f"SELECT c.id, c.realId, c.document, c._etag FROM c WHERE c.id in ({parameter_sequence})",
                "parameters": parameters
            }
            options = {'enableCrossPartitionQuery': True}

            # Run the query and store results
            results = list(self.client.QueryItems(self.__container_link, query, options))

            # Return a dict with realId as key and StoreItem as value
            return {r.get('realId'): self.__create_si(r) for r in results}
        else:
            raise Exception('cosmosdb_storage.read(): provide at least one key')
    except TypeError as e:
        raise e
