def shannon_entropy(pvec, base=2):
    # Define the logarithmic function based on the base
    if base == 2:
        def logfn(x):
            return -x * np.log2(x)
    elif base == np.e:
        def logfn(x):
            return -x * np.log(x)
    else:
        def logfn(x):
            return -x * np.log(x) / np.log(base)

    # Calculate the Shannon entropy
    h = 0.
    for x in pvec:
        if 0 < x < 1:
            h += logfn(x)
    return h
```

