def create_symmetric_key(self, algorithm, length):
    if algorithm not in self._symmetric_key_algorithms:
        raise exceptions.InvalidField(f"The cryptographic algorithm {algorithm} is not supported.")
    cryptography_algorithm = self._symmetric_key_algorithms[algorithm]
    if length not in cryptography_algorithm.key_sizes:
        raise exceptions.InvalidField(f"The length {length} is not valid for the algorithm {algorithm.name}.")
    self.logger.info(f"Generating a {algorithm.name} symmetric key with length: {length}")
    key_bytes = os.urandom(length // 8)
    try:
        cryptography_algorithm(key_bytes)
    except Exception as e:
        self.logger.exception(e)
        raise exceptions.CryptographicFailure("Invalid bytes for the provided cryptographic algorithm.")
    return {'value': key_bytes, 'format': enums.KeyFormatType.RAW}
```

