def read(self, queue):
    # Establish a Serial StreamReader connection using the provided serial settings
    conn = serial_asyncio.open_serial_connection(**self.serial_settings)
    reader, _ = yield from conn

    while True:
        # Read a line of data if available, otherwise yield control back to the loop
        data = yield from reader.readline()
        self.telegram_buffer.append(data.decode('ascii'))

        for telegram in self.telegram_buffer.get_all():
            try:
                # Parse the telegram and push it onto the queue
                queue.put_nowait(self.telegram_parser.parse(telegram))
            except ParseError as e:
