def _mkOp(fn):
    def op(*operands, key=None) -> RtlSignalBase:
        """
        :param operands: variadic parameter of input operands
        :param key: optional function applied on every operand before processing
        """
        assert operands, "operands must not be empty"
        top = None
        if key is not None:
            operands = map(key, operands)
        for s in operands:
            if top is None:
                top = s
            else:
                top = fn(top, s)
        return top
    return op
```

