def with_stdout(self, os_path=None, skip_sub_command=False, disk_closed_callback=None):
    sub_command = None if skip_sub_command else self.stdout_sub_command
    out, path = self._get_out_and_path(self.stdout, self.stdout_root, sub_command, os_path)
    try:
        if hasattr(out, 'stdin'):
            yield out.stdin
        else:
            yield out
    finally:
        if hasattr(out, 'stdin'):
            self._close(out.stdin)
        self._wait(out, path)
        self._close(out)
        if disk_closed_callback and path:
            disk_closed_callback(path)
