    self.logger.debug('entering receive loop')
    while True:
        try:
            data = self._sock_file.readline()
        except socket.error:
            data = None
        if not data:
            self.logger.info('server closed connection')
            self.close()
            return True
        data = data.rstrip()
        for pattern, callback in patterns:
            match = pattern.match(data)
            if match:
                callback(**match.groupdict())
