def enum(*sequential, **named):
    # Create a dictionary mapping sequential values to integers
    enums = dict(zip(sequential, range(len(sequential))), **named)

    # Create a copy of the enums dictionary
    enums['map'] = copy.copy(enums)

    # Create a reverse mapping from integers to sequential values
    enums['rmap'] = {}
    for key, value in enums.items():
        if isinstance(value, int):
